service.method:

UPDATE DLCON_IF_APP
   SET POSTPROCESSED = ${POSTPROCESSED}
 WHERE SMR_NUMBER = ${SUX_WKEY1}
 AND SEQ = #{APP_SEQ}


SELECT CODE AS LINK_CODE
  FROM ULNMA WITH(NOLOCK)
 WHERE HOUSE_CODE = '002'
   AND DOC_TYPE = ${LINK_TYPE}
   AND DOC_NUMBER = ${SMD_NUMBER}
   AND DOC_SEQ = '*'


UPDATE DLCON_IF_APP
   SET RECENT = 'N'
 WHERE SMR_NUMBER = ${SMR_NUMBER}


INSERT INTO DLCON_IF_APP 
     ( SMR_NUMBER
     , SEQ
     , RECENT
     , ERP_CODE
     , APP_STATUS
     , ADD_DATE
     , ADD_TIME
     , APPLY_FOR
     , CONFIRM_USER_ID
) VALUES (
       ${SMR_NUMBER}
     , (SELECT ISNULL(MAX(SEQ),0)+1 FROM DLCON_IF_APP WHERE SMR_NUMBER = ${SMR_NUMBER})
     , 'Y'
     , 'EASYSEAL'
     , 'TEMPSAVE'
     , ${current.DATE}
     , ${current.TIME}
     , ${APPLY_FOR}
     , ${session.ID}
)
